using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Windows.Forms;
namespace IDSketcher{
// Split contour edges at intersections, then retain the directed boundaries of
// the requested filled areas. Results stay vector contours, including holes.
static class VectorBooleanGeometry{
 struct P{public double X,Y;public P(double x,double y){X=x;Y=y;}public static P operator +(P a,P b){return new P(a.X+b.X,a.Y+b.Y);}public static P operator -(P a,P b){return new P(a.X-b.X,a.Y-b.Y);}public static P operator *(P a,double b){return new P(a.X*b,a.Y*b);}public PointF Point{get{return new PointF((float)X,(float)Y);}}}
 class Segment{public P A,B;public List<double> Cuts=new List<double>{0,1};}
 class Edge{public int A,B;public bool Used;}
 class Vertices{public double Epsilon;public List<P> Points=new List<P>();readonly Dictionary<string,List<int>> cells=new Dictionary<string,List<int>>();public int Get(P p){long x=(long)Math.Floor(p.X/Epsilon),y=(long)Math.Floor(p.Y/Epsilon);for(int i=-1;i<=1;i++)for(int j=-1;j<=1;j++){List<int> ids;if(cells.TryGetValue((x+i)+":"+(y+j),out ids))foreach(int id in ids){var d=Points[id]-p;if(d.X*d.X+d.Y*d.Y<=Epsilon*Epsilon)return id;}}string key=x+":"+y;List<int> bucket;if(!cells.TryGetValue(key,out bucket))cells[key]=bucket=new List<int>();int index=Points.Count;Points.Add(p);bucket.Add(index);return index;}}
 static double Cross(P a,P b){return a.X*b.Y-a.Y*b.X;}static double Dot(P a,P b){return a.X*b.X+a.Y*b.Y;}
 static void Cut(Segment s,double value){if(value>=-.0000001&&value<=1.0000001)s.Cuts.Add(Math.Max(0,Math.Min(1,value)));}
 static void Intersect(Segment a,Segment b){var u=a.B-a.A;var v=b.B-b.A;var w=b.A-a.A;double determinant=Cross(u,v);if(Math.Abs(determinant)>1e-10){double t=Cross(w,v)/determinant,q=Cross(w,u)/determinant;if(t>=-1e-8&&t<=1+1e-8&&q>=-1e-8&&q<=1+1e-8){Cut(a,t);Cut(b,q);}return;}if(Math.Abs(Cross(w,u))>1e-7*Math.Max(1,Math.Sqrt(Dot(u,u))))return;double aa=Dot(u,u),bb=Dot(v,v);if(aa<1e-16||bb<1e-16)return;Cut(a,Dot(b.A-a.A,u)/aa);Cut(a,Dot(b.B-a.A,u)/aa);Cut(b,Dot(a.A-b.A,v)/bb);Cut(b,Dot(a.B-b.A,v)/bb);}
 public static bool Contains(List<List<PointF>> contours,PointF p){bool inside=false;foreach(var c in contours)for(int i=0,j=c.Count-1;i<c.Count;j=i++){var a=c[i];var b=c[j];if((a.Y>p.Y)!=(b.Y>p.Y)&&p.X<(b.X-a.X)*(p.Y-a.Y)/(b.Y-a.Y)+a.X)inside=!inside;}return inside;}
 static bool Inside(List<List<PointF>> contours,P p){bool inside=false;foreach(var c in contours)for(int i=0,j=c.Count-1;i<c.Count;j=i++){var a=c[i];var b=c[j];if((a.Y>p.Y)!=(b.Y>p.Y)&&p.X<(b.X-a.X)*(p.Y-a.Y)/(b.Y-a.Y)+a.X)inside=!inside;}return inside;}
 static ulong Category(List<List<List<PointF>>> shapes,P p,string operation){if(operation=="SPLIT"){ulong mask=0;for(int i=0;i<shapes.Count;i++)if(Inside(shapes[i],p))mask|=1UL<<i;return mask;}if(operation=="MERGE")return shapes.Any(s=>Inside(s,p))?1UL:0UL;int cutter=operation=="REMOVE FRONT"?shapes.Count-1:0;if(Inside(shapes[cutter],p))return 0;for(int i=0;i<shapes.Count;i++)if(i!=cutter&&Inside(shapes[i],p))return 1;return 0;}
 public static Dictionary<ulong,List<List<PointF>>> Build(List<List<List<PointF>>> shapes,string operation){
  if(operation=="SPLIT"&&shapes.Count>32)throw new InvalidOperationException("Select up to 32 closed paths for SPLIT.");var segments=new List<Segment>();foreach(var shape in shapes)foreach(var contour in shape)for(int i=0;i<contour.Count;i++){var a=contour[i];var b=contour[(i+1)%contour.Count];if(a!=b)segments.Add(new Segment{A=new P(a.X,a.Y),B=new P(b.X,b.Y)});}if(segments.Count>16000)throw new InvalidOperationException("The selection is too complex. Simplify the paths first.");if(segments.Count==0)return new Dictionary<ulong,List<List<PointF>>>();
  double size=Math.Max(segments.Max(s=>Math.Max(s.A.X,s.B.X))-segments.Min(s=>Math.Min(s.A.X,s.B.X)),segments.Max(s=>Math.Max(s.A.Y,s.B.Y))-segments.Min(s=>Math.Min(s.A.Y,s.B.Y)));double epsilon=Math.Max(.00001,size*1e-8);
  for(int i=0;i<segments.Count;i++)for(int j=i+1;j<segments.Count;j++){var a=segments[i];var b=segments[j];if(Math.Max(a.A.X,a.B.X)+epsilon<Math.Min(b.A.X,b.B.X)||Math.Max(b.A.X,b.B.X)+epsilon<Math.Min(a.A.X,a.B.X)||Math.Max(a.A.Y,a.B.Y)+epsilon<Math.Min(b.A.Y,b.B.Y)||Math.Max(b.A.Y,b.B.Y)+epsilon<Math.Min(a.A.Y,a.B.Y))continue;Intersect(a,b);}
  var vertices=new Vertices{Epsilon=epsilon};var groups=new Dictionary<ulong,List<Edge>>();var seen=new HashSet<string>();Action<ulong,int,int> add=delegate(ulong group,int a,int b){if(group==0||a==b||!seen.Add(group+":"+a+":"+b))return;List<Edge> edges;if(!groups.TryGetValue(group,out edges))groups[group]=edges=new List<Edge>();edges.Add(new Edge{A=a,B=b});};
  foreach(var segment in segments){var cuts=segment.Cuts.OrderBy(v=>v).ToArray();var direction=segment.B-segment.A;for(int i=1;i<cuts.Length;i++){if(cuts[i]-cuts[i-1]<1e-10)continue;var a=segment.A+direction*cuts[i-1];var b=segment.A+direction*cuts[i];var d=b-a;double length=Math.Sqrt(Dot(d,d));if(length<epsilon)continue;var mid=(a+b)*.5;double step=Math.Min(length*.0001,epsilon*4);var normal=new P(-d.Y/length*step,d.X/length*step);ulong left=Category(shapes,mid+normal,operation),right=Category(shapes,mid-normal,operation);if(left==right)continue;int va=vertices.Get(a),vb=vertices.Get(b);add(left,va,vb);add(right,vb,va);}}
  var result=new Dictionary<ulong,List<List<PointF>>>();foreach(var group in groups){var edges=group.Value;var outgoing=edges.GroupBy(e=>e.A).ToDictionary(g=>g.Key,g=>g.ToList());var contours=new List<List<PointF>>();foreach(var first in edges){if(first.Used)continue;var ids=new List<int>();var edge=first;bool closed=false;for(int guard=0;guard<=edges.Count;guard++){if(edge.Used)break;edge.Used=true;ids.Add(edge.A);if(edge.B==first.A){closed=true;break;}List<Edge> choices;if(!outgoing.TryGetValue(edge.B,out choices))break;var incoming=vertices.Points[edge.A]-vertices.Points[edge.B];double reverse=Math.Atan2(incoming.Y,incoming.X),best=double.MaxValue;Edge next=null;foreach(var choice in choices){if(choice.Used)continue;var direction=vertices.Points[choice.B]-vertices.Points[choice.A];double clockwise=(reverse-Math.Atan2(direction.Y,direction.X)+Math.PI*4)%(Math.PI*2);if(clockwise<best){best=clockwise;next=choice;}}if(next==null)break;edge=next;}if(!closed)throw new InvalidOperationException("These paths could not be combined. Try simplifying the selection.");var points=ids.Select(id=>vertices.Points[id].Point).ToList();if(points.Count>=3&&Math.Abs(Area(points))>epsilon*epsilon)contours.Add(points);}result[group.Key]=contours;}return result;
 }
 public static double Area(List<PointF> points){double area=0;for(int i=0,j=points.Count-1;i<points.Count;j=i++)area+=(double)points[j].X*points[i].Y-(double)points[i].X*points[j].Y;return area/2;}
 public static List<List<List<PointF>>> Islands(List<List<PointF>> contours){var outer=contours.Where(c=>Area(c)>0).Select(c=>new List<List<PointF>>{c}).ToList();foreach(var hole in contours.Where(c=>Area(c)<0)){var owner=outer.Where(o=>Contains(new List<List<PointF>>{o[0]},hole[0])).OrderBy(o=>Math.Abs(Area(o[0]))).FirstOrDefault();if(owner!=null)owner.Add(hole);}return outer;}
}
partial class Canvas{
 public void BooleanVectors(string operation){if(!CanCombineClosed)return;var originals=Doc.Selected.Vectors.Where(v=>selectedPaths.Contains(v)).ToList();var geometry=VectorBooleanGeometry.Build(originals.Select(s=>s.ClosedContours()).ToList(),operation);var results=new List<VectorShape>();foreach(var group in geometry){var source=operation=="REMOVE FRONT"?originals[0]:originals.Last();if(operation=="SPLIT"){for(int i=0;i<originals.Count;i++)if((group.Key&(1UL<<i))!=0)source=originals[i];foreach(var island in VectorBooleanGeometry.Islands(group.Value))results.Add(VectorShape.FromContours(island,source));}else if(group.Value.Count>0)results.Add(VectorShape.FromContours(group.Value,source));}ReplaceCombinedVectors(originals,results);}
}
partial class Studio{
 public void TestVectorClipboardAndBooleans(){
  Func<float,float,float,float,VectorShape> rectangle=(x,y,w,h)=>new VectorShape{Kind="Polygon",Filled=true,Colour=Color.Blue,Points=new List<PointF>{new PointF(x,y),new PointF(x+w,y),new PointF(x+w,y+h),new PointF(x,y+h)}};
  var a=rectangle(0,0,100,100);var b=rectangle(50,0,100,100);var inputs=new List<List<List<PointF>>>{a.ClosedContours(),b.ClosedContours()};
  foreach(string op in new[]{"MERGE","REMOVE FRONT","REMOVE BACK","SPLIT"}){var result=VectorBooleanGeometry.Build(inputs,op);double area=result.Values.Sum(cs=>cs.Sum(c=>VectorBooleanGeometry.Area(c)));double expected=op=="MERGE"||op=="SPLIT"?15000:5000;if(Math.Abs(area-expected)>.01)throw new Exception(op+" overlap area "+area);if(op=="SPLIT"&&result.Count!=3)throw new Exception("Split must produce three regions");}
  foreach(float offset in new[]{0f,100f,150f}){var test=new List<List<List<PointF>>>{a.ClosedContours(),rectangle(offset,0,100,100).ClosedContours()};var result=VectorBooleanGeometry.Build(test,"MERGE");double area=result.Values.Sum(cs=>cs.Sum(c=>VectorBooleanGeometry.Area(c)));if(Math.Abs(area-(offset==0?10000:20000))>.01)throw new Exception("Identical/touching/disjoint union");}
  var nested=new List<List<List<PointF>>>{a.ClosedContours(),rectangle(25,25,50,50).ClosedContours()};var cut=VectorBooleanGeometry.Build(nested,"REMOVE FRONT").Values.Single();if(VectorBooleanGeometry.Contains(cut,new PointF(50,50))||!VectorBooleanGeometry.Contains(cut,new PointF(10,10))||VectorBooleanGeometry.Islands(cut).Count!=1)throw new Exception("Subtraction hole");
  var ellipse=new VectorShape{Kind="Ellipse",Points=new List<PointF>{new PointF(30,-20),new PointF(130,120)}};var curved=new List<List<List<PointF>>>{a.ClosedContours(),ellipse.ClosedContours()};foreach(string operation in new[]{"MERGE","REMOVE FRONT","REMOVE BACK","SPLIT"}){var result=VectorBooleanGeometry.Build(curved,operation);for(int x=-10;x<150;x+=7)for(int y=-30;y<140;y+=9){var p=new PointF(x+.234f,y+.321f);bool aa=VectorBooleanGeometry.Contains(curved[0],p),bb=VectorBooleanGeometry.Contains(curved[1],p),expected=operation=="REMOVE FRONT"?aa&&!bb:operation=="REMOVE BACK"?bb&&!aa:aa||bb;bool actual=result.Values.Any(contours=>VectorBooleanGeometry.Contains(contours,p));if(actual!=expected)throw new Exception("Curved boundary "+operation);}}
  a.GroupId=b.GroupId="testgroup";a.CornerRadius=12;a.Opacity=.6f;a.Fill.Mode=1;a.Fill.Start=Color.Red;
  previewing=true;Show();SetDocument(new Document("A4",100),null);AddTypedLayer(true);canvas.Doc.Selected.Vectors.Add(a);canvas.Doc.Selected.Vectors.Add(b);canvas.SelectAllVectors();canvas.Focus();string clipboard=null;writeVectorClipboard=value=>clipboard=value;readVectorClipboard=()=>clipboard;
  if(!HandleVectorClipboardKeys(Keys.Control|Keys.C)||clipboard==null)throw new Exception("Copy shortcut");int history=undo.Count;HandleVectorClipboardKeys(Keys.Control|Keys.V);if(canvas.Doc.Selected.Vectors.Count!=4||undo.Count!=history+1||canvas.Doc.Selected.Vectors[2].Points[0]!=new PointF(20,20))throw new Exception("Paste offset/undo");Travel(undo,redo);if(canvas.Doc.Selected.Vectors.Count!=2)throw new Exception("Paste undo");Travel(redo,undo);if(canvas.Doc.Selected.Vectors.Count!=4)throw new Exception("Paste redo");
  var pasted=canvas.Doc.Selected.Vectors[2];if(pasted.GroupId=="testgroup"||pasted.GroupId!=canvas.Doc.Selected.Vectors[3].GroupId||pasted.CornerRadius!=12||pasted.Fill.Start.ToArgb()!=Color.Red.ToArgb()||pasted.Opacity!=.6f)throw new Exception("Clipboard style/group preservation");
  SetDocument(new Document("A4",100),null);AddTypedLayer(true);canvas.Doc.Selected.Vectors.Add(rectangle(0,0,100,100));canvas.Doc.Selected.Vectors.Add(rectangle(25,25,50,50));canvas.SelectAllVectors();canvas.Focus();HandleVectorClipboardKeys(Keys.Control|Keys.J);var compound=canvas.Doc.Selected.Vectors.Single();using(var path=compound.Path())if(path.IsVisible(50,50)||!path.IsVisible(10,10))throw new Exception("Compound hole");if(compound.Copy().ContourStarts.Length!=2)throw new Exception("Compound deep copy");
  string file=System.IO.Path.Combine(System.IO.Path.GetTempPath(),Guid.NewGuid()+".idsk");try{canvas.Doc.Save(file);using(var loaded=Document.Load(file)){var restored=loaded.Selected.Vectors.Single();using(var path=restored.Path())if(restored.ContourStarts.Length!=2||path.IsVisible(50,50))throw new Exception("Compound persistence");}}finally{System.IO.File.Delete(file);}
  Travel(undo,redo);if(canvas.Doc.Selected.Vectors.Count!=2)throw new Exception("Compound undo");canvas.SelectAllVectors();canvas.BooleanVectors("SPLIT");if(canvas.Doc.Selected.Vectors.Count!=2)throw new Exception("Nested split islands");if(booleanButtons.Any(button=>button.TextAlign!=ContentAlignment.MiddleCenter))throw new Exception("Boolean captions");dirty=false;
 }
 readonly List<Button> booleanButtons=new List<Button>();
 void AddBooleanControls(FlowLayoutPanel tools){tools.Controls.Add(new Label{Text="BOOLEAN",Height=22,Width=144,Margin=new Padding(3,14,3,0)});foreach(string name in new[]{"MERGE","REMOVE FRONT","REMOVE BACK","SPLIT"}){string operation=name;var button=Theme.Button(name,delegate{try{canvas.BooleanVectors(operation);canvas.Focus();}catch(Exception error){MessageBox.Show(this,error.Message,"VECTOR OPERATION");}});button.Width=144;button.TextAlign=ContentAlignment.MiddleCenter;tools.Controls.Add(button);booleanButtons.Add(button);}UpdateBooleanControls();}
 void UpdateBooleanControls(){foreach(var button in booleanButtons)button.Enabled=canvas.CanCombineClosed;}
}
